                    connected <= 0;
                    connection_type <= 3'b000;
                end
                count <= 13'd4095;
            end
            else begin
                count <= count + 1'b1;
                GCpollend <= 0;
            end

        end

    end

    else begin  // if GC_enable is 0 then it is not the controller's turn to send data
